import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../services/api";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const login = async (event) => {
    event.preventDefault();
    setError("");

    try {
      const res = await api.post("/auth/login", { email, password });
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("user", JSON.stringify(res.data.user));
      navigate("/dashboard");
    } catch (err) {
      setError(err.response?.data?.message || "Unable to log in");
    }
  };

  return (
    <main className="auth-page">
      <form className="auth-card" onSubmit={login}>
        <h1>NGO Pro</h1>
        <p>Sign in to manage campaigns, donations and volunteers.</p>
        {error && <div className="error">{error}</div>}
        <label>
          Email
          <input value={email} placeholder="admin@ngo.test" onChange={(e) => setEmail(e.target.value)} />
        </label>
        <label>
          Password
          <input type="password" value={password} placeholder="password123" onChange={(e) => setPassword(e.target.value)} />
        </label>
        <button type="submit">Login</button>
        <Link to="/register">Create an account</Link>
      </form>
    </main>
  );
}
